UPDATE cut_cutover_checklist
SET status_code = 'INVALIDATED', invalidate_time = #{query.time}, invalidated_reason = #{query.reason},
    version = version + 1, updater = #{query.actorId}, update_time = #{query.time}
WHERE tenant_id = #{query.tenantId} AND task_id = #{query.taskId} AND id = #{query.sourceId}
  AND version = #{query.expectedVersion} AND status_code IN ('DRAFT','SUBMITTED') AND current_marker = 1 AND deleted = b'0'

UPDATE cut_cutover_checklist
SET version = version + 1,
    update_time = NOW(3)
WHERE tenant_id = #{query.tenantId}
  AND id = #{query.checklistId}
  AND version = #{query.expectedVersion}
  AND status_code = 'DRAFT'
  AND current_marker = 1
  AND deleted = b'0'
